function db(){static $p=null;if($p)return $p;$p=new PDO('mysql:host='.(getenv('DB_HOST')?:'127.0.0.1').';port='.(getenv('DB_PORT')?:'3306').';dbname='.(getenv('DB_NAME')?:'datasell').';charset=utf8mb4',getenv('DB_USER')?:'root',getenv('DB_PASS')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);return $p;}
function esc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function money($v){return '₦'.number_format((float)$v,2);} function ref($p='TX'){return $p.'-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(3)));} function live_mode(){return getenv('PROVIDER_LIVE')==='1';}
function csrf(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];} function verify_csrf(){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??''))throw new Exception('Your session expired. Refresh and try again.');}
function initdb(){
$p=db();
$p->exec("CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,fullname VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,phone VARCHAR(20) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,wallet_balance DECIMAL(14,2) NOT NULL DEFAULT 0,is_admin TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,type VARCHAR(50) NOT NULL,amount DECIMAL(14,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reference VARCHAR(80) NOT NULL UNIQUE,details TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS funding_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,amount DECIMAL(14,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reference VARCHAR(80) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS service_plans(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category VARCHAR(40) NOT NULL,provider VARCHAR(60) NOT NULL,name VARCHAR(120) NOT NULL,code VARCHAR(80) NOT NULL,price DECIMAL(14,2) NOT NULL,face_value DECIMAL(14,2) NULL,validity VARCHAR(80) NULL,plan_type VARCHAR(60) NULL,active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_plan(category,provider,code),INDEX(category),INDEX(provider)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS api_credentials(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL UNIQUE,key_prefix VARCHAR(24) NOT NULL,key_hash VARCHAR(255) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',last_used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id)) ENGINE=InnoDB;");
$cols=$p->query("SHOW COLUMNS FROM users")->fetchAll(PDO::FETCH_COLUMN);if(!in_array('account_type',$cols,true))$p->exec("ALTER TABLE users ADD account_type VARCHAR(20) NOT NULL DEFAULT 'customer' AFTER is_admin");if(!in_array('business_name',$cols,true))$p->exec("ALTER TABLE users ADD business_name VARCHAR(160) NULL AFTER account_type");
$count=(int)$p->query('SELECT COUNT(*) FROM service_plans')->fetchColumn();if($count===0){$seed=[['data','MTN','1GB Promo','MTN-1GB-250',250,null,'30 days','Promo/SME'],['data','MTN','500MB','MTN-500MB',180,null,'30 days','SME'],['data','MTN','2GB','MTN-2GB',700,null,'30 days','SME'],['data','MTN','3GB','MTN-3GB',1050,null,'30 days','SME'],['data','MTN','5GB','MTN-5GB',1750,null,'30 days','SME'],['data','Airtel','500MB','AIR-500MB',200,null,'30 days','Corporate'],['data','Airtel','1GB','AIR-1GB',400,null,'30 days','Corporate'],['data','Airtel','2GB','AIR-2GB',800,null,'30 days','Corporate'],['data','Glo','1GB','GLO-1GB',350,null,'30 days','Corporate'],['data','9mobile','1GB','9M-1GB',350,null,'30 days','Corporate'],['airtime','MTN','₦100 Airtime','MTN-A100',98,100,null,'VTU'],['airtime','MTN','₦500 Airtime','MTN-A500',490,500,null,'VTU'],['airtime','Airtel','₦100 Airtime','AIR-A100',98,100,null,'VTU'],['airtime','Glo','₦100 Airtime','GLO-A100',98,100,null,'VTU'],['airtime','9mobile','₦100 Airtime','9M-A100',98,100,null,'VTU'],['cable','DStv','DStv Yanga','DSTV-YANGA',3500,null,'30 days','Bouquet'],['cable','DStv','DStv Compact','DSTV-COMPACT',12500,null,'30 days','Bouquet'],['cable','GOtv','GOtv Jolli','GOTV-JOLLI',3950,null,'30 days','Bouquet'],['cable','StarTimes','Nova','START-NOVA',1700,null,'30 days','Bouquet'],['exam','WAEC','WAEC Result Checker PIN','WAEC-PIN',4000,null,null,'PIN'],['exam','NECO','NECO Result Checker Token','NECO-PIN',1500,null,null,'PIN'],['exam','NABTEB','NABTEB Result Checker PIN','NABTEB-PIN',1500,null,null,'PIN'],['electricity','AEDC','AEDC Electricity','AEDC',0,null,null,'Prepaid/Postpaid'],['electricity','EKEDC','EKEDC Electricity','EKEDC',0,null,null,'Prepaid/Postpaid'],['electricity','IBEDC','IBEDC Electricity','IBEDC',0,null,null,'Prepaid/Postpaid'],['electricity','IKEDC','IKEDC Electricity','IKEDC',0,null,null,'Prepaid/Postpaid'],['electricity','JED','Jos Electricity','JED',0,null,null,'Prepaid/Postpaid'],['electricity','KAEDCO','Kaduna Electric','KAEDCO',0,null,null,'Prepaid/Postpaid'],['electricity','KEDCO','Kano Electric','KEDCO',0,null,null,'Prepaid/Postpaid'],['electricity','PHED','Port Harcourt Electric','PHED',0,null,null,'Prepaid/Postpaid']];$s=$p->prepare('INSERT INTO service_plans(category,provider,name,code,price,face_value,validity,plan_type,sort_order) VALUES(?,?,?,?,?,?,?,?,?)');foreach($seed as $i=>$r)$s->execute([...$r,$i]);}}
try{initdb();}catch(Throwable $e){}
function me(){if(empty($_SESSION['uid']))return null;$s=db()->prepare('SELECT id,fullname,email,phone,wallet_balance,is_admin,account_type,business_name,created_at FROM users WHERE id=?');$s->execute([$_SESSION['uid']]);return $s->fetch()?:null;}
function plans($cat){$s=db()->prepare('SELECT * FROM service_plans WHERE category=? AND active=1 ORDER BY sort_order,id');$s->execute([$cat]);return $s->fetchAll();}
function navitem($key,$label,$page){return '<a class="nav-item'.($key===$page?' active':'').'" href="?page='.$key.'"><span>'.esc($label).'</span></a>';}
$action=$_POST['action']??'';$msg='';$err='';$newApiKey=null;
try{if($action){verify_csrf();
if($action==='register'){$name=trim($_POST['fullname']??'');$email=strtolower(trim($_POST['email']??''));$phone=preg_replace('/\D/','',$_POST['phone']??'');$pw=$_POST['password']??'';if(strlen($name)<3||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($phone)<10||strlen($pw)<6)throw new Exception('Please enter valid registration details.');$s=db()->prepare('INSERT INTO users(fullname,email,phone,password_hash) VALUES(?,?,?,?)');$s->execute([$name,$email,$phone,password_hash($pw,PASSWORD_DEFAULT)]);$_SESSION['uid']=db()->lastInsertId();header('Location:?page=dashboard');exit;}
if($action==='login'){$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$r=$s->fetch();if(!$r||!password_verify($_POST['password']??'',$r['password_hash']))throw new Exception('Invalid email or password.');$_SESSION['uid']=$r['id'];header('Location:?page=dashboard');exit;}
if($action==='logout'){session_destroy();header('Location:/');exit;}
if($action==='change_role'){$u=me();$role=$_POST['account_type']??'customer';if(!in_array($role,['customer','reseller','api'],true))throw new Exception('Invalid account type.');db()->prepare('UPDATE users SET account_type=?,business_name=? WHERE id=?')->execute([$role,trim($_POST['business_name']??'')?:null,$u['id']]);$msg='Account workspace updated.';}
if($action==='generate_api_key'){$u=me();if(!$u||!in_array($u['account_type'],['api','reseller'],true))throw new Exception('Switch to API User or Reseller first.');$plain='ih_live_'.bin2hex(random_bytes(24));$prefix=substr($plain,0,16);db()->prepare('INSERT INTO api_credentials(user_id,key_prefix,key_hash,status) VALUES(?,?,?,"active") ON DUPLICATE KEY UPDATE key_prefix=VALUES(key_prefix),key_hash=VALUES(key_hash),status="active",last_used_at=NULL')->execute([$u['id'],$prefix,password_hash($plain,PASSWORD_DEFAULT)]);$newApiKey=$plain;$msg='New API key generated. Copy it now; it will not be shown again.';}
if($action==='fund'){$u=me();$a=(float)($_POST['amount']??0);if($a<100)throw new Exception('Minimum funding request is ₦100.');db()->prepare('INSERT INTO funding_requests(user_id,amount,reference) VALUES(?,?,?)')->execute([$u['id'],$a,ref('FUND')]);$msg='Funding request submitted.';}
if($action==='purchase'){$u=me();$id=(int)($_POST['plan_id']??0);$cat=$_POST['category']??'';$recipient=trim($_POST['recipient']??'');$custom=(float)($_POST['custom_amount']??0);$s=db()->prepare('SELECT * FROM service_plans WHERE id=? AND active=1');$s->execute([$id]);$pl=$s->fetch();if(!$pl||$pl['category']!==$cat)throw new Exception('Selected product is unavailable.');$amount=$cat==='electricity'?$custom:(float)$pl['price'];if($amount<=0)throw new Exception('Enter a valid amount.');$details=json_encode(['provider'=>$pl['provider'],'plan'=>$pl['name'],'plan_code'=>$pl['code'],'recipient'=>$recipient,'mode'=>live_mode()?'live':'staging']);if(live_mode()){if($amount>$u['wallet_balance'])throw new Exception('Insufficient wallet balance.');$p=db();$p->beginTransaction();$p->prepare('UPDATE users SET wallet_balance=wallet_balance-? WHERE id=? AND wallet_balance>=?')->execute([$amount,$u['id'],$amount]);$p->prepare('INSERT INTO transactions(user_id,type,amount,status,reference,details) VALUES(?,?,?,?,?,?)')->execute([$u['id'],$cat,$amount,'pending',ref(),$details]);$p->commit();$msg='Order queued for provider processing.';}else{db()->prepare('INSERT INTO transactions(user_id,type,amount,status,reference,details) VALUES(?,?,?,?,?,?)')->execute([$u['id'],$cat,$amount,'pending',ref('DEMO'),$details]);$msg='Staging order created without debiting your wallet.';}}
if($action==='approve'&&me()['is_admin']){$id=(int)$_POST['id'];$p=db();$p->beginTransaction();$s=$p->prepare("SELECT * FROM funding_requests WHERE id=? AND status='pending' FOR UPDATE");$s->execute([$id]);$r=$s->fetch();if(!$r)throw new Exception('Funding request not found.');$p->prepare("UPDATE funding_requests SET status='approved' WHERE id=?")->execute([$id]);$p->prepare('UPDATE users SET wallet_balance=wallet_balance+? WHERE id=?')->execute([$r['amount'],$r['user_id']]);$p->prepare('INSERT INTO transactions(user_id,type,amount,status,reference,details) VALUES(?,?,?,?,?,?)')->execute([$r['user_id'],'wallet_funding',$r['amount'],'successful',$r['reference'],json_encode(['source'=>'admin'])]);$p->commit();$msg='Wallet funded successfully.';}
if($action==='save_plan'&&me()['is_admin']){$vals=[trim($_POST['category']??''),trim($_POST['provider']??''),trim($_POST['name']??''),trim($_POST['code']??''),(float)($_POST['price']??0),($_POST['face_value']??'')===''?null:(float)$_POST['face_value'],trim($_POST['validity']??''),trim($_POST['plan_type']??''),isset($_POST['active'])?1:0];if(!$vals[0]||!$vals[1]||!$vals[2]||!$vals[3])throw new Exception('Plan fields are incomplete.');db()->prepare('INSERT INTO service_plans(category,provider,name,code,price,face_value,validity,plan_type,active) VALUES(?,?,?,?,?,?,?,?,?)')->execute($vals);$msg='Service plan saved.';}
}}catch(Throwable $e){$err=$e->getMessage();}
$page=$_GET['page']??'home';$u=me();$protected=['dashboard','data','airtime','electricity','cable','exam','wallet','transactions','profile','reseller','api-dashboard','admin'];if(in_array($page,$protected,true)&&!$u){header('Location:?page=login');exit;}if($page==='admin'&&$u&&!$u['is_admin']){header('Location:?page=dashboard');exit;}if($page==='reseller'&&$u&&$u['account_type']!=='reseller'){header('Location:?page=profile');exit;}if($page==='api-dashboard'&&$u&&!in_array($u['account_type'],['api','reseller'],true)){header('Location:?page=profile');exit;}
if($page==='transactions'&&isset($_GET['export'])&&$u){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="ihlink-datasub-statement.csv"');$o=fopen('php://output','w');fputcsv($o,['Reference','Type','Amount','Status','Date']);$s=db()->prepare('SELECT reference,type,amount,status,created_at FROM transactions WHERE user_id=? ORDER BY id DESC');$s->execute([$u['id']]);foreach($s as $r)fputcsv($o,$r);fclose($o);exit;}
